constraints:
1 ≤ N ≤ 10^{18}

expected time complexity: O(log(N))
expected auxiliary space: O(Height of the recursive call stack)

standard_solution_code:
from functools import lru_cache

class Solution:

	@lru_cache()
	def recSol(self, n):
		if n == 1:
			return (1, 0, 0, 1)
		(a1, b1, c1, d1) = self.recSol(n // 2)
		(a2, b2, c2, d2) = self.recSol(n - n // 2)
		a3 = a1 * (a2 + c2) + b1 * a2
		b3 = a1 * (b2 + d2) + b1 * b2
		c3 = c1 * (a2 + c2) + d1 * a2
		d3 = c1 * (b2 + d2) + d1 * b2
		a3 %= 10 ** 9 + 7
		b3 %= 10 ** 9 + 7
		c3 %= 10 ** 9 + 7
		d3 %= 10 ** 9 + 7
		return (a3, b3, c3, d3)

	def countStrings(self, N):
		return sum(list(self.recSol(N))) % (10 ** 9 + 7)
